<?php
declare(strict_types=1);
final class SpreadsheetTransfer {
    public static function read(string $path,bool $raw=false):array{$z=new ZipArchive();if(filesize($path)>2097152||$z->open($path)!==true)throw new InvalidArgumentException(t('Choose an XLSX up to 2 MiB.'));try{$total=0;for($i=0;$i<$z->numFiles;$i++){$total+=$z->statIndex($i)['size'];if($total>8388608)throw new InvalidArgumentException(t('Unpacked spreadsheet exceeds 8 MiB.'));}$parse=function(string $name)use($z){$text=$z->getFromName($name);if($text===false)return null;if(str_contains(strtoupper($text),'<!DOCTYPE'))throw new InvalidArgumentException(t('External XML definitions are unsupported.'));$doc=simplexml_load_string($text,SimpleXMLElement::class,LIBXML_NONET);if(!$doc)throw new InvalidArgumentException(t('Invalid spreadsheet XML.'));return $doc;};$strings=[];$shared=$parse('xl/sharedStrings.xml');if($shared)foreach($shared->si as $s){$parts=$s->xpath('.//*[local-name()="t"]');$strings[]=implode('',array_map(fn($t)=>(string)$t,$parts));}$sheet=$parse('xl/worksheets/sheet1.xml');if(!$sheet)throw new InvalidArgumentException(t('First worksheet is missing.'));$rows=[];foreach($sheet->sheetData->row as $r){$row=[];foreach($r->c as $c){$ref=(string)$c['r'];preg_match('/^([A-Z]+)[0-9]+$/',$ref,$m);if(!$m)throw new InvalidArgumentException(t('Invalid cell reference.'));$column=0;foreach(str_split($m[1])as $letter)$column=$column*26+ord($letter)-64;if($column>100)throw new InvalidArgumentException(t('At most 100 columns supported.'));if(isset($c->f))throw new InvalidArgumentException(t('Replace formulas with values before importing.'));$type=(string)$c['t'];$v=$type==='s'?($strings[(int)$c->v]??''):($type==='inlineStr'?(string)$c->is->t:(string)$c->v);$row[$column-1]=$v;}if(!$row)continue;$rows[]=$row;if(count($rows)>1001)throw new InvalidArgumentException(t('At most 1000 data rows.'));}$head=array_shift($rows);if(!$head)throw new InvalidArgumentException(t('Spreadsheet needs column headers.'));$out=[];foreach($rows as $row){$d=[];foreach($head as $col=>$label)$d[strtolower(trim($label))]=$row[$col]??'';$out[]=$d;}return $raw?$out:PlatformService::preview(json_encode($out,JSON_THROW_ON_ERROR),'json');}finally{$z->close();}}
    public static function write():string{$path=tempnam(sys_get_temp_dir(),'lifeos-xlsx-');$z=new ZipArchive();try{$z->open($path,ZipArchive::OVERWRITE);$z->addFromString('[Content_Types].xml','<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>');$z->addFromString('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');$z->addFromString('xl/workbook.xml','<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Tasks" sheetId="1" r:id="rId1"/></sheets></workbook>');$z->addFromString('xl/_rels/workbook.xml.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>');$xml='<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>';$rows=array_merge([['title','due','status']],array_map('array_values',Db::all('SELECT title,due,status FROM tasks ORDER BY id')));foreach($rows as $i=>$row){$xml.='<row r="'.($i+1).'">';foreach($row as $j=>$v)$xml.='<c r="'.chr(65+$j).($i+1).'" t="inlineStr"><is><t>'.htmlspecialchars((string)$v,ENT_XML1|ENT_QUOTES,'UTF-8').'</t></is></c>';$xml.='</row>';}$z->addFromString('xl/worksheets/sheet1.xml',$xml.'</sheetData></worksheet>');$z->close();return file_get_contents($path);}finally{@unlink($path);}}
}
